(() => {
  const dialog  = document.getElementById('delete-dialog');
  const trigger = document.getElementById('delete-trigger');
  const cancelBtn = document.getElementById('cancel-btn');
  const confirmBtn = document.getElementById('confirm-delete-btn');

  // Open
  trigger.addEventListener('click', () => {
    dialog.showModal();
    // Move initial focus to Cancel (not the destructive action)
    cancelBtn.focus();
  });

  // Cancel — close without deleting
  cancelBtn.addEventListener('click', () => dialog.close('cancel'));

  // Confirm — perform deletion
  confirmBtn.addEventListener('click', () => {
    dialog.close('delete');
  });

  // Handle result after dialog closes
  dialog.addEventListener('close', () => {
    if (dialog.returnValue === 'delete') {
      // In a real app this would call the delete API.
      // For the demo we replace the card content with a status message.
      const card = document.querySelector('.image-card');
      const liveRegion = document.getElementById('delete-status');
      card.style.opacity = '0.4';
      card.style.pointerEvents = 'none';
      liveRegion.textContent = 'Image deleted from your library.';
    }
    // Browser automatically returns focus to the trigger element.
  });

  // Close on backdrop click (outside dialog-inner)
  dialog.addEventListener('click', (e) => {
    if (e.target === dialog) dialog.close('cancel');
  });
})();
